<?php
namespace App\Services\Media;
use App\Contracts\ProtectedMediaStorage;use App\Jobs\ProcessMediaAsset;use App\Models\{Group,MediaAsset,MediaVariant,Photo,StorageLedgerEntry,UploadBatchFile,User};use Illuminate\Http\UploadedFile;use Illuminate\Support\Facades\DB;use Illuminate\Support\Str;use RuntimeException;use Throwable;
class QueuedMediaIngestor {private const TYPES=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'];public function __construct(private ProtectedMediaStorage $storage){}public function ingest(UploadedFile $file,Group $group,User $user,UploadBatchFile $batchFile):Photo{$mime=(new \finfo(FILEINFO_MIME_TYPE))->file($file->getRealPath());$ext=self::TYPES[$mime]??null;if(!$ext||$file->getSize()<=0||$file->getSize()>(int)config('media.max_upload_bytes'))throw new RuntimeException('Invalid image content or size.');if(!in_array(strtolower($file->getClientOriginalExtension()),$ext==='jpg'?['jpg','jpeg']:[$ext],true))throw new RuntimeException('The filename extension does not match the image content.');$key=$this->storage->putFile(config('media.prefixes.originals').'/groups/'.$group->id,$file,$ext);try{[$photo,$asset]=DB::transaction(function()use($file,$group,$user,$batchFile,$mime,$key){$size=$this->storage->size($key);$info=@getimagesize($file->getRealPath());$photo=Photo::create(['group_id'=>$group->id,'uploader_id'=>$user->id,'filename'=>basename($key),'original_filename'=>basename($file->getClientOriginalName()),'path'=>$key,'thumbnail_path'=>$key,'file_size'=>$size,'mime_type'=>$mime,'width'=>$info[0]??null,'height'=>$info[1]??null]);$asset=MediaAsset::create(['uuid'=>(string)Str::uuid(),'photo_id'=>$photo->id,'group_id'=>$group->id,'owner_id'=>$group->creator_id,'uploader_id'=>$user->id,'storage_disk'=>$this->storage->disk(),'original_object_key'=>$key,'original_filename'=>basename($file->getClientOriginalName()),'mime_type'=>$mime,'size_bytes'=>$size,'checksum_sha256'=>$this->storage->checksum($key),'width'=>$info[0]??null,'height'=>$info[1]??null,'state'=>'queued','migration_state'=>'native']);MediaVariant::create(['media_asset_id'=>$asset->id,'variant_type'=>'original','storage_disk'=>$this->storage->disk(),'object_key'=>$key,'mime_type'=>$mime,'size_bytes'=>$size,'checksum_sha256'=>$asset->checksum_sha256,'width'=>$asset->width,'height'=>$asset->height,'state'=>'ready']);StorageLedgerEntry::create(['owner_id'=>$asset->owner_id,'group_id'=>$group->id,'media_asset_id'=>$asset->id,'event_type'=>'original_stored','byte_delta'=>$size,'idempotency_key'=>'original-'.$asset->uuid]);User::whereKey($asset->owner_id)->increment('storage_used',$size);$batchFile->update(['media_asset_id'=>$asset->id,'state'=>'queued']);return[$photo,$asset];});ProcessMediaAsset::dispatch($asset->id,$batchFile->id)->afterCommit();return$photo;}catch(Throwable $e){$this->storage->delete($key);throw$e;}}}
